/* Screens generated by the real application renderer, not calculator emulation.
 * SVG text uses host fonts; calculator glyph rasterization still needs device QA. */
#include "ui.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static App a;
typedef struct {
    FILE *f;
    unsigned clip;
} Svg;
static const char *colors[] = {"#ffffff", "#2e3136", "#e5e8eb", "#f5f7f9", "#c43e3b", "#2f6fb9",
                               "#2d8968", "#8256a4", "#dd8f29", "#141618", "#e8f0fc", "#757c86"};
static const char *color(unsigned c) {
    return colors[c < 12 ? c : 0];
}
static void rect(void *user, int x, int y, int w, int h, unsigned c) {
    Svg *s = user;
    if (w > 0 && h > 0)
        fprintf(s->f, "<rect x='%d' y='%d' width='%d' height='%d' fill='%s'/>\n", x, y, w, h,
                color(c));
}
static void line(void *user, int x, int y, int xx, int yy, unsigned c) {
    Svg *s = user;
    fprintf(s->f, "<path d='M%d %dL%d %d' stroke='%s' fill='none'/>\n", x, y, xx, yy, color(c));
}
static void text(void *user, int x, int y, const char *str, unsigned c) {
    Svg *s = user;
    if (!*str)
        return;
    fprintf(s->f,
            "<text x='%d' y='%d' fill='%s' font-family='monospace' font-size='9' textLength='%zu' "
            "lengthAdjust='spacingAndGlyphs'>",
            x, y + 7, color(c), strlen(str) * 6);
    for (const char *p = str; *p; p++) {
        if (*p == '&')
            fputs("&amp;", s->f);
        else if (*p == '<')
            fputs("&lt;", s->f);
        else if (*p == '>')
            fputs("&gt;", s->f);
        else
            fputc(*p, s->f);
    }
    fputs("</text>\n", s->f);
}
static void clip(void *user, int x, int y, int w, int h) {
    Svg *s = user;
    if (s->clip)
        fputs("</g>\n", s->f);
    s->clip++;
    fprintf(s->f,
            "<defs><clipPath id='c%u'><rect x='%d' y='%d' width='%d' "
            "height='%d'/></clipPath></defs><g clip-path='url(#c%u)'>\n",
            s->clip, x, y, w, h, s->clip);
}
static void row(unsigned i, const char *str) {
    strncpy(a.m.s.row[i].text, str, DCE_TEXT - 1);
    if (a.m.s.rows <= i)
        a.m.s.rows = i + 1;
}
int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: render_host scene output.svg\n");
        return 2;
    }
    app_init(&a);
    int scene = atoi(argv[1]);
    switch (scene) {
    case 0:
        row(0, "y=x^2-6x+5");
        row(1, "y=-x+7");
        break;
    case 1:
        row(0, "f(x)=(x^2+1)/(x-3)");
        row(1, "g(x)=sqrt(x+4)");
        a.mode = 1;
        break;
    case 2:
        row(0, "y_1~mx_1+b");
        a.m.s.points = 5;
        for (unsigned i = 0; i < 5; i++) {
            a.m.s.x[i] = i + 1;
            a.m.s.y[i] = 2 * (i + 1) + 1;
        }
        a.m.s.xmin = -1;
        a.m.s.xmax = 7;
        a.m.s.ymin = -1;
        a.m.s.ymax = 13;
        break;
    case 3:
        row(0, "y=2x+[1,2,3,4]");
        a.mode = 2;
        break;
    case 4:
        row(0, "(x-2)^2+(y+1)^2=25");
        a.mode = 2;
        a.m.s.xmin = -8;
        a.m.s.xmax = 12;
        a.m.s.ymin = -7.2;
        a.m.s.ymax = 5.2;
        break;
    case 5:
        row(0, "y=ax^2+b");
        a.mode = 6;
        break;
    case 6:
        row(0, "2k+5~17");
        a.mode = 8;
        break;
    case 7:
        row(0, "y_1~mx_1+b");
        a.m.s.points = 5;
        for (unsigned i = 0; i < 5; i++) {
            a.m.s.x[i] = i + 1;
            a.m.s.y[i] = 2 * (i + 1) + 1;
        }
        a.mode = 3;
        break;
    default:
        return 2;
    }
    app_rebuild(&a);
    ed_init(&a.editor, a.m.s.row[0].text);
    strcpy(a.notice, "General math / practice | 2nd MODE: save");
    Svg s = {fopen(argv[2], "w"), 0};
    if (!s.f) {
        perror(argv[2]);
        return 1;
    }
    fputs(
        "<svg xmlns='http://www.w3.org/2000/svg' width='320' height='240' viewBox='0 0 320 240'>\n",
        s.f);
    Draw d = {&s, rect, line, text, clip};
    app_draw(&a, &d);
    if (s.clip)
        fputs("</g>\n", s.f);
    fputs("</svg>\n", s.f);
    fclose(s.f);
    return 0;
}
